namespace APItrackGRN.Api.Services;

/// <summary>The same 12pt bold-italic wordmark used in the browser and PDF, without printer-installed fonts.</summary>
internal static class LabelWordmark
{
    private const int Width = 503;
    private const int Height = 78;
    private static readonly byte[] Raster = Convert.FromBase64String("");
    public static string Zpl(int dpi, int left, int top)
    {
        var width = Math.Max(1, (int)Math.Round(Width * dpi / 600d));
        var height = Math.Max(1, (int)Math.Round(Height * dpi / 600d));
        var bytesPerRow = (width + 7) / 8;
        var target = new byte[bytesPerRow * height];
        for (var y = 0; y < height; y++)
        for (var x = 0; x < width; x++)
        {
            var sx = Math.Min(Width - 1, (int)Math.Round(x * (Width - 1d) / Math.Max(1, width - 1)));
            var sy = Math.Min(Height - 1, (int)Math.Round(y * (Height - 1d) / Math.Max(1, height - 1)));
            if ((Raster[sy * ((Width + 7) / 8) + sx / 8] & (128 >> (sx % 8))) != 0)
                target[y * bytesPerRow + x / 8] |= (byte)(128 >> (x % 8));
        }
        return $"^FO{left},{top}^GFA,{target.Length},{target.Length},{bytesPerRow},{Convert.ToHexString(target)}^FS\n";
    }
}
